export const automotiveBaselineHtml = "<!-- ===================== AUTOMOTIVE — SECTION SUB NAV (STICKY TABS) ===================== -->\n<link href=\"https://fonts.googleapis.com/css2?family=Poppins:wght@500;600;700;800&display=swap\" rel=\"stylesheet\"/>\n\n<style>\n  :root{\n    --navy:#020C4F;\n    --indigo:#313B86;\n    --violet:#625AD8;\n    --accent:#1F9CE4;\n\n    --tabText:#6B7280;\n    --tabActive: var(--indigo);\n    --line:#E6E8EF;\n    --bg:#ffffff;\n\n    /* Height of this subnav (used for scroll offset) */\n    --autoSecTabsH: 58px;\n  }\n\n  .autoTabs, .autoTabs *{box-sizing:border-box;}\n\n  /* Sticky subnav */\n  .autoTabs{\n    position:sticky;\n    top:0;\n    z-index:9999;\n    background:var(--bg);\n    border-bottom:1px solid var(--line);\n    font-family:'Poppins',system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;\n    isolation:isolate;\n  }\n\n  .autoTabs__inner{\n    max-width:1200px;\n    margin:0 auto;\n    padding:0 20px;\n    height:var(--autoSecTabsH);\n    display:flex;\n    align-items:center;\n    gap:14px;\n  }\n\n  .autoTabs__label{\n    font-weight:900;\n    letter-spacing:.08em;\n    text-transform:uppercase;\n    color:#111;\n    font-size:12px;\n    padding-right:14px;\n    border-right:1px solid var(--line);\n    margin-right:2px;\n    white-space:nowrap;\n  }\n\n  .autoTabs__list{\n    display:flex;\n    align-items:center;\n    gap:0;\n    flex-wrap:nowrap;\n    overflow:auto;\n    scrollbar-width:none;\n  }\n  .autoTabs__list::-webkit-scrollbar{display:none;}\n\n  .autoTabs__link{\n    position:relative;\n    display:inline-flex;\n    align-items:center;\n    height:var(--autoSecTabsH);\n    padding:0 18px;\n    text-decoration:none;\n    text-transform:uppercase;\n    letter-spacing:.06em;\n    font-size:12px;\n    font-weight:800;\n    color:var(--tabText);\n    white-space:nowrap;\n  }\n\n  /* vertical separators */\n  .autoTabs__link + .autoTabs__link{\n    border-left:1px solid var(--line);\n  }\n\n  /* active underline */\n  .autoTabs__link.is-active{\n    color:var(--tabActive);\n  }\n  .autoTabs__link.is-active::after{\n    content:\"\";\n    position:absolute;\n    left:14px;\n    right:14px;\n    bottom:0;\n    height:3px;\n    background:var(--tabActive);\n    border-radius:999px;\n  }\n\n  .autoTabs__link:hover{ color:#111; }\n\n  /* Optional: use this class on each section wrapper so anchors don't hide under the sticky tabs:\n     <section id=\"...\" class=\"autoAnchorFix\"> ... */\n  .autoAnchorFix{\n    scroll-margin-top: calc(var(--autoSecTabsH) + 14px);\n  }\n\n  @media(max-width:980px){\n    .autoTabs__inner{padding:0 14px;}\n    .autoTabs__label{display:none;}\n    .autoTabs__link{padding:0 14px;}\n  }\n</style>\n\n<nav class=\"autoTabs\" aria-label=\"Automotive page navigation\">\n  <div class=\"autoTabs__inner\">\n    <div class=\"autoTabs__label\">AUTOMOTIVE</div>\n\n    <div class=\"autoTabs__list\">\n      <!-- ✅ IDs mapped to your Automotive page sections -->\n      <a class=\"autoTabs__link is-active\" href=\"#auto-hero\">Overview</a>\n      <a class=\"autoTabs__link\" href=\"#auto-challenges\">Key Challenges</a>\n      <a class=\"autoTabs__link\" href=\"#auto-how-we-help\">How We Help</a>\n      <a class=\"autoTabs__link\" href=\"#auto-why-us\">Why Us</a>\n      <a class=\"autoTabs__link\" href=\"#auto-cta\">Next Steps</a>\n    </div>\n  </div>\n</nav>\n\n<script>\n(function(){\n  const nav = document.querySelector('.autoTabs');\n  if(!nav) return;\n\n  const links = Array.from(nav.querySelectorAll('.autoTabs__link'));\n  const getOffset = () => {\n    const h = nav.getBoundingClientRect().height || 58;\n    return h + 12; // breathing space so section titles are visible\n  };\n\n  // Smooth scroll with offset\n  links.forEach(a=>{\n    a.addEventListener('click', (e)=>{\n      const href = a.getAttribute('href');\n      if(!href || !href.startsWith('#')) return;\n\n      const el = document.querySelector(href);\n      if(!el) return;\n\n      e.preventDefault();\n      const y = el.getBoundingClientRect().top + window.pageYOffset - getOffset();\n      window.scrollTo({ top:y, behavior:'smooth' });\n      history.replaceState(null, '', href);\n    });\n  });\n\n  // Active state on scroll\n  const targets = links\n    .map(a => document.querySelector(a.getAttribute('href')))\n    .filter(Boolean);\n\n  const setActive = (id) => {\n    links.forEach(a=>{\n      a.classList.toggle('is-active', a.getAttribute('href') === '#'+id);\n    });\n  };\n\n  const isElementor =\n    document.body.classList.contains('elementor-editor-active') ||\n    document.body.classList.contains('elementor-editor-preview') ||\n    !!document.querySelector('#elementor-editor-wrapper');\n\n  if(isElementor) return;\n  if(!('IntersectionObserver' in window)) return;\n\n  const io = new IntersectionObserver((entries)=>{\n    const visible = entries\n      .filter(e=>e.isIntersecting)\n      .sort((a,b)=>b.intersectionRatio-a.intersectionRatio)[0];\n\n    if(visible && visible.target && visible.target.id){\n      setActive(visible.target.id);\n    }\n  }, { root:null, threshold:[0.2,0.35,0.5,0.65] });\n\n  targets.forEach(t=>{\n    if(t.id) io.observe(t);\n  });\n})();\n</script>\n\n<!-- ===================== AUTOMOTIVE — HERO (WHITE ONLY, IMAGE RIGHT — CLONE OF A&D/INSURANCE) ===================== -->\n<link href=\"https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700;800;900&display=swap\" rel=\"stylesheet\"/>\n\n<style>\n  :root{\n    /* brand colours */\n    --navy:#020C4F;\n    --indigo:#313B86;\n    --violet:#625AD8;\n    --accent:#1F9CE4;\n\n    --ink:#0B0F1A;\n    --muted:#3C4160;\n    --line:rgba(49,59,134,.16);\n    --white:#ffffff;\n\n    --max:1200px;\n  }\n\n  .autoHeroW, .autoHeroW *{box-sizing:border-box;}\n  .autoHeroW{\n    font-family:'Poppins',system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;\n    color:var(--ink);\n    background:#fff;\n    padding:88px 20px 34px;\n  }\n\n  .autoHeroW__inner{\n    max-width:var(--max);\n    margin:0 auto;\n    display:grid;\n    grid-template-columns:minmax(0,1.08fr) minmax(0,.92fr);\n    gap:44px;\n    align-items:center;\n  }\n\n  .autoHeroW__eyebrow{\n    margin:0 0 12px;\n    font-size:12px;\n    letter-spacing:.18em;\n    text-transform:uppercase;\n    color:var(--indigo);\n    font-weight:900;\n  }\n\n  .autoHeroW__title{\n    margin:0 0 14px;\n    font-size:clamp(34px,4.2vw,56px);\n    line-height:1.06;\n    font-weight:900;\n    color:var(--navy);\n  }\n\n  .autoHeroW__sub{\n    margin:0 0 14px;\n    font-size:clamp(16px,2vw,20px);\n    line-height:1.55;\n    font-weight:700;\n    color:var(--indigo);\n    max-width:820px;\n  }\n\n  .autoHeroW__p{\n    margin:0;\n    font-size:15.5px;\n    line-height:1.78;\n    color:var(--muted);\n    max-width:920px;\n  }\n  .autoHeroW__p + .autoHeroW__p{ margin-top:14px; }\n\n  /* Right visual (image placeholder) */\n  .autoHeroW__media{\n    border-radius:22px;\n    overflow:hidden;\n    border:1px solid var(--line);\n    box-shadow:0 18px 44px rgba(0,0,0,.08);\n    background:\n      radial-gradient(circle at 20% 15%, rgba(98,90,216,.22), transparent 55%),\n      radial-gradient(circle at 85% 25%, rgba(31,156,228,.22), transparent 55%),\n      radial-gradient(circle at 50% 95%, rgba(49,59,134,.18), transparent 60%),\n      linear-gradient(180deg, rgba(2,12,79,.06), rgba(49,59,134,.04));\n    min-height:320px;\n    position:relative;\n  }\n\n  .autoHeroW__img{\n    width:100%;\n    height:100%;\n    display:block;\n    object-fit:cover;\n  }\n\n  .autoHeroW__badge{\n    position:absolute;\n    left:16px; top:16px;\n    display:inline-flex;\n    align-items:center;\n    gap:10px;\n    padding:10px 12px;\n    border-radius:999px;\n    border:1px solid rgba(49,59,134,.18);\n    background:rgba(255,255,255,.76);\n    backdrop-filter:blur(8px);\n    color:var(--navy);\n    font-size:12px;\n    font-weight:900;\n  }\n  .autoHeroW__dot{\n    width:10px;height:10px;border-radius:999px;\n    background:linear-gradient(135deg,var(--violet),var(--accent));\n    box-shadow:0 0 0 5px rgba(31,156,228,.12);\n  }\n\n  @media (max-width:980px){\n    .autoHeroW{padding:74px 16px 22px;}\n    .autoHeroW__inner{grid-template-columns:1fr; gap:22px;}\n    .autoHeroW__media{min-height:240px;}\n  }\n</style>\n\n<section class=\"autoHeroW\" id=\"auto-hero\">\n  <div class=\"autoHeroW__inner\">\n    <!-- LEFT CONTENT -->\n    <div>\n      <p class=\"autoHeroW__eyebrow\">Automotive Sector – Industry Solutions &amp; Transformation Services</p>\n\n      <h1 class=\"autoHeroW__title\">\n        Reinventing Automotive Enterprises Through Strategy, Operations, and Digital-Led Transformation\n      </h1>\n\n      <p class=\"autoHeroW__sub\">\n        The Automotive industry is undergoing a foundational shift—driven by electric mobility, connected vehicles, software-defined systems,\n        tightening emissions and safety norms, supply chain volatility, and evolving customer expectations.\n      </p>\n\n      <p class=\"autoHeroW__p\">\n        Traditional business models are being challenged by new entrants, rapid technology cycles, and cost pressures across the value chain.\n        At [Your Firm Name], we partner with Automotive organisations to convert complexity into clarity and strategy into measurable outcomes.\n        Our integrated approach—spanning strategy, operations, digital enablement, and capability building—enables OEMs, Tier-1 suppliers,\n        and automotive service providers to accelerate growth, drive efficiency, and build competitive advantage that lasts.\n      </p>\n    </div>\n\n    <!-- RIGHT VISUAL -->\n    <div class=\"autoHeroW__media\">\n      <div class=\"autoHeroW__badge\">\n        <span class=\"autoHeroW__dot\"></span> Automotive Transformation\n      </div>\n      <img\n        class=\"autoHeroW__img\"\n        src=\"https://mediumpurple-ant-531485.hostingersite.com/wp-content/uploads/2025/12/marc-olivier-jodoin-K9GMQEETUAw-unsplash-scaled.jpg\"\n        alt=\"Automotive enterprise transformation (placeholder)\"\n      />\n    </div>\n  </div>\n</section>\n\n<!-- ===================== AUTOMOTIVE — KEY CHALLENGES (DESKTOP: LIST + DETAIL | MOBILE: CARD ACCORDION) ===================== -->\n<link href=\"https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700;800;900&display=swap\" rel=\"stylesheet\"/>\n\n<style>\n  :root{\n    --navy:#020C4F;\n    --indigo:#313B86;\n    --violet:#625AD8;\n    --accent:#1F9CE4;\n\n    --ink:#0B0F1A;\n    --muted:#4B5168;\n    --line:rgba(49,59,134,.16);\n  }\n\n  .autoK, .autoK *{ box-sizing:border-box; }\n\n  .autoK{\n    padding:92px 20px;\n    font-family:'Poppins',system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;\n    color:var(--ink);\n    background:\n      radial-gradient(circle at 18% 0%, rgba(98,90,216,.10), transparent 55%),\n      radial-gradient(circle at 95% 30%, rgba(49,59,134,.10), transparent 55%),\n      radial-gradient(circle at 70% 110%, rgba(2,12,79,.08), transparent 60%),\n      rgba(49,59,134,.03);\n  }\n\n  .autoK__inner{max-width:1200px;margin:0 auto;}\n\n  .autoK__top{\n    display:grid;\n    grid-template-columns:minmax(0,.95fr) minmax(0,1.05fr);\n    gap:32px;\n    margin-bottom:22px;\n  }\n\n  .autoK__eyebrow{\n    font-size:12px;\n    letter-spacing:.18em;\n    text-transform:uppercase;\n    color:var(--indigo);\n    font-weight:900;\n    margin:0 0 10px;\n  }\n\n  .autoK__title{\n    margin:0;\n    font-size:clamp(38px,4.4vw,56px);\n    line-height:1.05;\n    font-weight:900;\n    color:var(--navy);\n  }\n\n  .autoK__intro{\n    margin:22px 0 0;\n    font-size:15.5px;\n    line-height:1.75;\n    color:#3C4160;\n    max-width:780px;\n  }\n\n  .autoK__grid{\n    display:grid;\n    grid-template-columns:minmax(0,.86fr) minmax(0,1.14fr);\n    gap:26px;\n  }\n\n  /* LEFT RAIL */\n  .autoK__rail{\n    border:1px solid rgba(49,59,134,.18);\n    border-radius:22px;\n    background:rgba(255,255,255,.78);\n    backdrop-filter:blur(10px);\n    box-shadow:0 18px 44px rgba(0,0,0,.06);\n    overflow:hidden;\n  }\n\n  .autoK__railTop{\n    padding:16px;\n    display:flex;\n    justify-content:space-between;\n    border-bottom:1px solid rgba(49,59,134,.12);\n  }\n\n  .autoK__railLabel{\n    font-size:12px;\n    letter-spacing:.18em;\n    text-transform:uppercase;\n    font-weight:900;\n    color:var(--navy);\n  }\n\n  .autoK__item{\n    display:grid;\n    grid-template-columns:44px 1fr;\n    gap:12px;\n    padding:14px 16px;\n    border-top:1px solid rgba(49,59,134,.10);\n    background:transparent;\n    cursor:pointer;\n    text-align:left;\n  }\n\n  .autoK__item:first-child{border-top:0;}\n\n  .autoK__icon{\n    width:40px;height:40px;\n    border-radius:14px;\n    display:grid;\n    place-items:center;\n    background:rgba(49,59,134,.05);\n    border:1px solid rgba(49,59,134,.14);\n  }\n\n  .autoK__itemTitle{\n    margin:0;\n    font-size:14.5px;\n    font-weight:900;\n    color:var(--navy);\n  }\n\n  .autoK__itemPreview{\n    margin:4px 0 0;\n    font-size:13px;\n    color:#5B6282;\n    line-height:1.5;\n    display:-webkit-box;\n    -webkit-line-clamp:2;\n    -webkit-box-orient:vertical;\n    overflow:hidden;\n  }\n\n  .autoK__item[aria-selected=\"true\"]{\n    background:rgba(31,156,228,.06);\n  }\n\n  /* RIGHT PANEL */\n  .autoK__panel{\n    border:1px solid rgba(49,59,134,.18);\n    border-radius:22px;\n    background:rgba(255,255,255,.86);\n    box-shadow:0 18px 44px rgba(0,0,0,.06);\n    display:flex;\n    flex-direction:column;\n    min-height:520px;\n  }\n\n  .autoK__panelHead{\n    padding:16px 18px;\n    border-bottom:1px solid rgba(49,59,134,.12);\n  }\n\n  .autoK__panelTitle{\n    margin:0;\n    font-size:22px;\n    font-weight:900;\n    color:var(--navy);\n  }\n\n  .autoK__panelBody{padding:18px;}\n\n  .autoK__bullets{\n    list-style:none;\n    padding:0;\n    margin:0;\n    display:grid;\n    gap:12px;\n  }\n\n  .autoK__bullets li{\n    display:flex;\n    gap:10px;\n    font-size:14.5px;\n    line-height:1.65;\n    color:#2E334D;\n  }\n\n  .autoK__dot{\n    width:10px;height:10px;border-radius:50%;\n    margin-top:7px;\n    background:rgba(31,156,228,.22);\n    outline:3px solid rgba(31,156,228,.10);\n  }\n\n  /* MOBILE */\n  @media(max-width:820px){\n    .autoK__grid{grid-template-columns:1fr;}\n    .autoK__panel{display:none;}\n  }\n</style>\n\n<section class=\"autoK\" id=\"auto-challenges\">\n  <div class=\"autoK__inner\">\n\n    <div class=\"autoK__top\">\n      <div>\n        <p class=\"autoK__eyebrow\">Automotive Sector</p>\n        <h2 class=\"autoK__title\">Key Challenges</h2>\n      </div>\n      <p class=\"autoK__intro\">\n        Automotive organisations face simultaneous disruption across technology, regulation, and operating models—placing\n        pressure on growth, cost, resilience, and execution across the value chain.\n      </p>\n    </div>\n\n    <div class=\"autoK__grid\">\n      <!-- LEFT -->\n      <div class=\"autoK__rail\" role=\"tablist\">\n        <div class=\"autoK__railTop\">\n          <div class=\"autoK__railLabel\">Challenges</div>\n        </div>\n\n        <button class=\"autoK__item\" aria-selected=\"true\" data-key=\"c1\">\n          <div class=\"autoK__icon\">⚡</div>\n          <div>\n            <p class=\"autoK__itemTitle\">Market Disruption & Growth Pressure</p>\n            <p class=\"autoK__itemPreview\">Electrification, new mobility entrants, demand volatility, and shifting customer expectations.</p>\n          </div>\n        </button>\n\n        <button class=\"autoK__item\" aria-selected=\"false\" data-key=\"c2\">\n          <div class=\"autoK__icon\">🏭</div>\n          <div>\n            <p class=\"autoK__itemTitle\">Operational Inefficiencies & Cost Constraints</p>\n            <p class=\"autoK__itemPreview\">Legacy production systems, high changeover costs, fragmented planning, and commodity volatility.</p>\n          </div>\n        </button>\n\n        <button class=\"autoK__item\" aria-selected=\"false\" data-key=\"c3\">\n          <div class=\"autoK__icon\">🔗</div>\n          <div>\n            <p class=\"autoK__itemTitle\">Complex Supply Chain & Resilience Gaps</p>\n            <p class=\"autoK__itemPreview\">Multi-tier visibility gaps, semiconductor and battery risks, inventory imbalance.</p>\n          </div>\n        </button>\n\n        <button class=\"autoK__item\" aria-selected=\"false\" data-key=\"c4\">\n          <div class=\"autoK__icon\">🧠</div>\n          <div>\n            <p class=\"autoK__itemTitle\">Digital & Technology Adoption Challenges</p>\n            <p class=\"autoK__itemPreview\">Siloed IT, slow modernisation, limited analytics, underused Industry 4.0.</p>\n          </div>\n        </button>\n\n        <button class=\"autoK__item\" aria-selected=\"false\" data-key=\"c5\">\n          <div class=\"autoK__icon\">📜</div>\n          <div>\n            <p class=\"autoK__itemTitle\">Regulatory & Quality Compliance</p>\n            <p class=\"autoK__itemPreview\">Stricter emissions and safety norms, recalls, homologation complexity.</p>\n          </div>\n        </button>\n      </div>\n\n      <!-- RIGHT -->\n      <aside class=\"autoK__panel\">\n        <div class=\"autoK__panelHead\">\n          <h3 class=\"autoK__panelTitle\" id=\"autoK-title\">Market Disruption & Growth Pressure</h3>\n        </div>\n        <div class=\"autoK__panelBody\">\n          <ul class=\"autoK__bullets\" id=\"autoK-bullets\"></ul>\n        </div>\n      </aside>\n    </div>\n\n  </div>\n</section>\n\n<script>\n(function(){\n  const data={\n    c1:[\n      \"Shift from internal combustion to electrification\",\n      \"Rising competition from new mobility entrants\",\n      \"Demand for customised, connected experiences\",\n      \"Fluctuating market demand cycles and price sensitivity\"\n    ],\n    c2:[\n      \"Legacy production systems with limited flexibility\",\n      \"High changeover costs across models and variants\",\n      \"Fragmented planning and scheduling across plants\",\n      \"Cost pressures from commodity volatility\"\n    ],\n    c3:[\n      \"Multi-tier supply chains with limited visibility\",\n      \"Risk concentration in semiconductors and batteries\",\n      \"Slow replenishment and inventory imbalances\",\n      \"Weak supplier risk signals and recovery mechanisms\"\n    ],\n    c4:[\n      \"Siloed IT across engineering, production, and aftermarket\",\n      \"Limited use of analytics for demand and quality\",\n      \"Slow legacy system modernisation\",\n      \"Underutilised automation and Industry 4.0 solutions\"\n    ],\n    c5:[\n      \"Stricter safety, emissions, and data protection regulations\",\n      \"Multi-region homologation complexity\",\n      \"High cost of quality escapes and recalls\",\n      \"Capital tied up in compliance and audit readiness\"\n    ]\n  };\n\n  const root=document.querySelector('#auto-challenges');\n  if(!root) return;\n\n  const items=[...root.querySelectorAll('.autoK__item')];\n  const bullets=root.querySelector('#autoK-bullets');\n  const title=root.querySelector('#autoK-title');\n\n  function render(key,label){\n    title.textContent=label;\n    bullets.innerHTML=data[key].map(x=>`<li><span class=\"autoK__dot\"></span><span>${x}</span></li>`).join('');\n  }\n\n  render('c1','Market Disruption & Growth Pressure');\n\n  items.forEach(btn=>{\n    btn.addEventListener('click',()=>{\n      items.forEach(b=>b.setAttribute('aria-selected','false'));\n      btn.setAttribute('aria-selected','true');\n      render(btn.dataset.key, btn.querySelector('.autoK__itemTitle').textContent);\n    });\n  });\n})();\n</script>\n\n<!-- ===================== AUTOMOTIVE — HOW WE HELP (DESKTOP SLIDER + MOBILE ACCORDION) ===================== -->\n<link href=\"https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700;800&display=swap\" rel=\"stylesheet\" />\n\n<style>\n:root{\n  --navy:#020C4F;\n  --indigo:#313B86;\n  --violet:#625AD8;\n  --accent:#1F9CE4;\n\n  --ink:#0B0F1A;\n  --muted:#4B5168;\n  --line:rgba(49,59,134,.18);\n  --card:#ffffff;\n\n  /* ✅ change if you want a different image for Automotive */\n  --autow-bg-img:url(\"https://mediumpurple-ant-531485.hostingersite.com/wp-content/uploads/2025/12/marc-olivier-jodoin-K9GMQEETUAw-unsplash-scaled.jpg\");\n}\n\n/* scope */\n.autoW, .autoW *{ box-sizing:border-box; }\n\n.autoW{\n  position:relative;\n  padding:96px 20px;\n  font-family:'Poppins',system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;\n  color:var(--ink);\n  overflow:hidden;\n\n  background:\n    radial-gradient(circle at 18% 0%, rgba(98,90,216,.10), transparent 55%),\n    radial-gradient(circle at 95% 30%, rgba(31,156,228,.10), transparent 55%),\n    radial-gradient(circle at 70% 110%, rgba(2,12,79,.08), transparent 60%),\n    rgba(49,59,134,.03);\n}\n\n.autoW::before{\n  content:\"\";\n  position:absolute;\n  inset:0;\n  background:\n    linear-gradient(90deg, rgba(2,12,79,.80), rgba(2,12,79,.25) 55%, rgba(2,12,79,0) 100%),\n    var(--autow-bg-img);\n  background-size:cover;\n  background-position:center;\n  opacity:.95;\n  z-index:0;\n  pointer-events:none;\n}\n\n.autoW::after{\n  content:\"\";\n  position:absolute;\n  inset:0;\n  background:linear-gradient(180deg, rgba(255,255,255,.06), rgba(255,255,255,.02));\n  z-index:0;\n  pointer-events:none;\n}\n\n.autoW__inner{\n  position:relative;\n  z-index:1;\n  max-width:1200px;\n  margin:0 auto;\n  width:100%;\n  min-width:0;\n}\n\n.autoW__eyebrow{\n  font-size:12px;\n  letter-spacing:.18em;\n  text-transform:uppercase;\n  color:rgba(255,255,255,.85);\n  font-weight:800;\n  margin:0 0 10px;\n}\n\n.autoW__title{\n  margin:0 0 22px;\n  font-size:clamp(34px,4vw,56px);\n  line-height:1.08;\n  font-weight:900;\n  color:#fff;\n}\n\n.autoW__layout{\n  display:grid;\n  grid-template-columns:minmax(0,0.38fr) minmax(0,0.62fr);\n  gap:56px;\n  align-items:stretch;\n  width:100%;\n  min-width:0;\n}\n\n/* entrance animation */\n.autoW__left,\n.autoW__right{\n  opacity:0;\n  transition:opacity .85s ease, transform .85s cubic-bezier(.2,.9,.2,1);\n}\n.autoW__left{ transform:translateX(-44px); }\n.autoW__right{ transform:translateX(44px); }\n.autoW.is-in .autoW__left,\n.autoW.is-in .autoW__right{\n  opacity:1;\n  transform:translateX(0);\n}\n\n/* ===================== DESKTOP LEFT ===================== */\n.autoW__left{\n  border:1px solid rgba(255,255,255,.16);\n  border-radius:20px;\n  background:rgba(255,255,255,.06);\n  backdrop-filter: blur(10px);\n  box-shadow:0 12px 32px rgba(0,0,0,.14);\n  padding:18px;\n  min-width:0;\n}\n\n.autoW__leftTitle{\n  margin:0 0 12px;\n  font-size:26px;\n  font-weight:900;\n  color:#fff;\n}\n\n.autoW__nav{\n  display:grid;\n  gap:10px;\n  margin-top:10px;\n  min-width:0;\n}\n\n.autoW__navBtn{\n  width:100%;\n  border:1px solid rgba(255,255,255,.14);\n  background:rgba(255,255,255,.05);\n  border-radius:14px;\n  padding:14px 14px;\n  cursor:pointer;\n  display:flex;\n  align-items:center;\n  justify-content:space-between;\n  gap:12px;\n  text-align:left;\n  transition:transform .18s ease, background .18s ease, border-color .18s ease;\n  min-width:0;\n  white-space:normal;\n}\n\n.autoW__navBtn:hover{\n  transform:translateY(-1px);\n  background:rgba(255,255,255,.07);\n  border-color:rgba(255,255,255,.18);\n}\n\n.autoW__navLeft{\n  display:flex;\n  align-items:center;\n  gap:10px;\n  min-width:0;\n  flex:1 1 auto;\n}\n\n.autoW__navMark{\n  width:10px; height:10px;\n  border-radius:999px;\n  background:linear-gradient(135deg,var(--violet),var(--accent));\n  box-shadow:0 0 0 6px rgba(31,156,228,.12);\n  flex:0 0 auto;\n}\n\n.autoW__navText{ min-width:0; }\n\n.autoW__itemTitle{\n  margin:0;\n  font-size:14.5px;\n  font-weight:800;\n  color:#fff;\n  line-height:1.2;\n  white-space:nowrap;\n  overflow:hidden;\n  text-overflow:ellipsis;\n}\n\n.autoW__itemHint{\n  margin:6px 0 0;\n  font-size:12.5px;\n  color:rgba(255,255,255,.80);\n  line-height:1.3;\n  white-space:nowrap;\n  overflow:hidden;\n  text-overflow:ellipsis;\n}\n\n.autoW__navArrow{\n  width:34px; height:34px;\n  border-radius:12px;\n  display:grid;\n  place-items:center;\n  border:1px solid rgba(255,255,255,.16);\n  color:#fff;\n  background:rgba(255,255,255,.06);\n  flex:0 0 auto;\n}\n\n.autoW__navBtn[aria-selected=\"true\"]{\n  background:rgba(255,255,255,.10);\n  border-color:rgba(255,255,255,.24);\n}\n\n/* ===================== DESKTOP RIGHT SLIDER ===================== */\n.autoW__right{\n  position:relative;\n  border-radius:22px;\n  min-height:560px;\n  min-width:0;\n}\n\n.autoW__stage{\n  position:relative;\n  height:100%;\n  min-height:560px;\n  padding:0 68px; /* peeks */\n  min-width:0;\n}\n\n.autoW__card{\n  position:absolute;\n  top:0;\n  left:50%;\n  transform:translateX(-50%);\n  width:86%;\n  height:100%;\n  border-radius:22px;\n  background:rgba(255,255,255,.96);\n  border:1px solid rgba(49,59,134,.18);\n  box-shadow:0 28px 70px rgba(0,0,0,.22);\n  overflow:hidden;\n  display:flex;\n  flex-direction:column;\n  transition:transform .42s cubic-bezier(.2,.9,.2,1), opacity .25s ease;\n}\n\n.autoW__card.is-active{ z-index:3; opacity:1; }\n.autoW__card.is-prev,\n.autoW__card.is-next{\n  z-index:2;\n  width:82%;\n  opacity:.78;\n  background:rgba(255,255,255,.78);\n  box-shadow:0 22px 60px rgba(0,0,0,.18);\n}\n.autoW__card.is-prev{ transform:translateX(-50%) translateX(-110px) scale(.965); }\n.autoW__card.is-next{ transform:translateX(-50%) translateX(110px) scale(.965); }\n\n.autoW__top{\n  padding:18px 22px 14px;\n  border-bottom:1px solid rgba(49,59,134,.14);\n  background:\n    radial-gradient(circle at 0% 0%, rgba(98,90,216,.10), transparent 55%),\n    radial-gradient(circle at 100% 0%, rgba(31,156,228,.10), transparent 55%),\n    #fff;\n}\n\n.autoW__kicker{\n  margin:0 0 6px;\n  font-size:12px;\n  letter-spacing:.16em;\n  text-transform:uppercase;\n  color:var(--indigo);\n  font-weight:900;\n}\n\n.autoW__cardTitle{\n  margin:0;\n  font-size:22px;\n  line-height:1.2;\n  font-weight:900;\n  color:var(--navy);\n}\n\n.autoW__body{\n  padding:16px 22px 18px;\n  overflow:auto;\n}\n\n.autoW__lead{\n  margin:0 0 12px;\n  font-size:15px;\n  line-height:1.75;\n  color:#2E334D;\n}\n\n.autoW__label{\n  margin:12px 0 8px;\n  font-size:14px;\n  font-weight:800;\n  color:var(--ink);\n}\n\n.autoW__list{ margin:0; padding-left:18px; }\n.autoW__list li{\n  margin:0 0 7px;\n  font-size:14.5px;\n  line-height:1.65;\n  color:#2E334D;\n}\n\n.autoW__impact{\n  margin-top:14px;\n  padding:12px 12px;\n  border-radius:14px;\n  border:1px solid rgba(49,59,134,.12);\n  background:rgba(49,59,134,.03);\n  border-left:4px solid var(--accent);\n  font-size:14.5px;\n  line-height:1.7;\n  color:#3C4160;\n}\n.autoW__impact b{ color:var(--navy); }\n\n/* peek preview */\n.autoW__card.is-prev .autoW__lead,\n.autoW__card.is-next .autoW__lead{\n  display:-webkit-box;\n  -webkit-line-clamp:2;\n  -webkit-box-orient:vertical;\n  overflow:hidden;\n  max-height:3.7em;\n}\n.autoW__card.is-prev .autoW__label,\n.autoW__card.is-next .autoW__label,\n.autoW__card.is-prev .autoW__list,\n.autoW__card.is-next .autoW__list,\n.autoW__card.is-prev .autoW__impact,\n.autoW__card.is-next .autoW__impact{\n  display:none;\n}\n\n.autoW__ctrl{\n  position:absolute;\n  top:50%;\n  transform:translateY(-50%);\n  width:46px;height:46px;\n  border-radius:14px;\n  border:1px solid rgba(255,255,255,.22);\n  background:rgba(0,0,0,.50);\n  color:#fff;\n  display:grid;\n  place-items:center;\n  cursor:pointer;\n  transition:transform .18s ease, background .18s ease, border-color .18s ease;\n  z-index:5;\n  user-select:none;\n}\n.autoW__ctrl:hover{\n  transform:translateY(-50%) scale(1.03);\n  background:rgba(255,255,255,.16);\n  border-color:rgba(255,255,255,.30);\n}\n.autoW__ctrl--prev{ left:12px; }\n.autoW__ctrl--next{ right:12px; }\n\n/* ===================== MOBILE (NO HORIZONTAL) ===================== */\n.autoW__mWrap{ display:none; }\n\n@media (max-width:980px){\n  .autoW{ padding:78px 16px; }\n  .autoW__layout{ grid-template-columns:1fr; gap:14px; }\n\n  .autoW__right{ display:none !important; }\n\n  .autoW__left{ padding:14px; border-radius:18px; }\n  .autoW__leftTitle{ font-size:18px; margin-bottom:10px; }\n  .autoW__nav{ display:none !important; }\n\n  .autoW__mWrap{ display:grid; gap:12px; }\n\n  .autoW__mCard{\n    border:1px solid rgba(255,255,255,.18);\n    background:rgba(255,255,255,.08);\n    backdrop-filter: blur(10px);\n    border-radius:18px;\n    box-shadow:0 12px 28px rgba(0,0,0,.14);\n    overflow:hidden;\n  }\n\n  .autoW__mBtn{\n    width:100%;\n    border:0;\n    background:transparent;\n    padding:14px 14px;\n    display:flex;\n    align-items:center;\n    justify-content:space-between;\n    gap:12px;\n    cursor:pointer;\n    text-align:left;\n    color:#fff;\n  }\n\n  .autoW__mLeft{\n    display:flex;\n    align-items:flex-start;\n    gap:10px;\n    min-width:0;\n    flex:1 1 auto;\n  }\n\n  .autoW__mTitle{\n    margin:0;\n    font-size:14.5px;\n    font-weight:900;\n    line-height:1.25;\n    color:#fff;\n  }\n\n  .autoW__mHint{\n    margin:6px 0 0;\n    font-size:12.5px;\n    line-height:1.35;\n    color:rgba(255,255,255,.82);\n    overflow-wrap:anywhere;\n  }\n\n  .autoW__mChevron{\n    width:34px;height:34px;\n    border-radius:12px;\n    border:1px solid rgba(255,255,255,.16);\n    background:rgba(255,255,255,.06);\n    display:grid;\n    place-items:center;\n    color:#fff;\n    flex:0 0 auto;\n    transition:transform .2s ease;\n  }\n\n  .autoW__mAcc{ display:none; padding:0 14px 14px; }\n  .autoW__mCard[aria-expanded=\"true\"] .autoW__mAcc{ display:block; }\n  .autoW__mCard[aria-expanded=\"true\"] .autoW__mChevron{ transform:rotate(180deg); }\n\n  .autoW__mContent{\n    border-radius:16px;\n    background:rgba(255,255,255,.96);\n    border:1px solid rgba(49,59,134,.18);\n    box-shadow:0 18px 44px rgba(0,0,0,.18);\n    overflow:hidden;\n  }\n\n  .autoW__mTop{\n    padding:14px 14px 12px;\n    border-bottom:1px solid rgba(49,59,134,.14);\n    background:\n      radial-gradient(circle at 0% 0%, rgba(98,90,216,.10), transparent 55%),\n      radial-gradient(circle at 100% 0%, rgba(31,156,228,.10), transparent 55%),\n      #fff;\n  }\n\n  .autoW__mKicker{\n    margin:0 0 6px;\n    font-size:11.5px;\n    letter-spacing:.14em;\n    text-transform:uppercase;\n    color:var(--indigo);\n    font-weight:900;\n  }\n\n  .autoW__mCardTitle{\n    margin:0;\n    font-size:20px;\n    line-height:1.2;\n    font-weight:950;\n    color:var(--navy);\n  }\n\n  .autoW__mBody{ padding:12px 14px 14px; }\n\n  .autoW__mLead{\n    margin:0 0 10px;\n    font-size:14.5px;\n    line-height:1.7;\n    color:#2E334D;\n  }\n\n  .autoW__mLabel{\n    margin:10px 0 8px;\n    font-size:13.5px;\n    font-weight:900;\n    color:var(--ink);\n  }\n\n  .autoW__mList{ margin:0; padding-left:18px; }\n  .autoW__mList li{\n    margin:0 0 7px;\n    font-size:14.2px;\n    line-height:1.65;\n    color:#2E334D;\n    overflow-wrap:anywhere;\n  }\n\n  .autoW__mImpact{\n    margin-top:12px;\n    padding:10px 12px;\n    border-radius:14px;\n    border:1px solid rgba(49,59,134,.12);\n    background:rgba(49,59,134,.03);\n    border-left:4px solid var(--accent);\n    font-size:14.2px;\n    line-height:1.7;\n    color:#3C4160;\n  }\n  .autoW__mImpact b{ color:var(--navy); }\n}\n</style>\n\n<section class=\"autoW\" id=\"auto-how-we-help\" aria-label=\"How we help the Automotive sector\">\n  <div class=\"autoW__inner\">\n    <p class=\"autoW__eyebrow\">Automotive Sector</p>\n    <h2 class=\"autoW__title\">How We Help the Automotive Sector</h2>\n\n    <div class=\"autoW__layout\">\n      <!-- DESKTOP LEFT -->\n      <aside class=\"autoW__left\">\n        <h3 class=\"autoW__leftTitle\">Our Services</h3>\n\n        <div class=\"autoW__nav\" role=\"tablist\" aria-label=\"Automotive service pillars\">\n          <button class=\"autoW__navBtn\" role=\"tab\" aria-selected=\"true\" data-i=\"0\">\n            <div class=\"autoW__navLeft\">\n              <span class=\"autoW__navMark\" aria-hidden=\"true\"></span>\n              <div class=\"autoW__navText\">\n                <p class=\"autoW__itemTitle\">Growth &amp; Strategy</p>\n                <p class=\"autoW__itemHint\">Future-fit choices</p>\n              </div>\n            </div>\n            <span class=\"autoW__navArrow\" aria-hidden=\"true\">›</span>\n          </button>\n\n          <button class=\"autoW__navBtn\" role=\"tab\" aria-selected=\"false\" data-i=\"1\">\n            <div class=\"autoW__navLeft\">\n              <span class=\"autoW__navMark\" aria-hidden=\"true\"></span>\n              <div class=\"autoW__navText\">\n                <p class=\"autoW__itemTitle\">Shared Services &amp; GCC Excellence</p>\n                <p class=\"autoW__itemHint\">Scalable operations</p>\n              </div>\n            </div>\n            <span class=\"autoW__navArrow\" aria-hidden=\"true\">›</span>\n          </button>\n\n          <button class=\"autoW__navBtn\" role=\"tab\" aria-selected=\"false\" data-i=\"2\">\n            <div class=\"autoW__navLeft\">\n              <span class=\"autoW__navMark\" aria-hidden=\"true\"></span>\n              <div class=\"autoW__navText\">\n                <p class=\"autoW__itemTitle\">Tech-Enabled Transformation</p>\n                <p class=\"autoW__itemHint\">Digitalise value chain</p>\n              </div>\n            </div>\n            <span class=\"autoW__navArrow\" aria-hidden=\"true\">›</span>\n          </button>\n\n          <button class=\"autoW__navBtn\" role=\"tab\" aria-selected=\"false\" data-i=\"3\">\n            <div class=\"autoW__navLeft\">\n              <span class=\"autoW__navMark\" aria-hidden=\"true\"></span>\n              <div class=\"autoW__navText\">\n                <p class=\"autoW__itemTitle\">ESG &amp; Sustainable Value Creation</p>\n                <p class=\"autoW__itemHint\">Responsible growth</p>\n              </div>\n            </div>\n            <span class=\"autoW__navArrow\" aria-hidden=\"true\">›</span>\n          </button>\n\n          <button class=\"autoW__navBtn\" role=\"tab\" aria-selected=\"false\" data-i=\"4\">\n            <div class=\"autoW__navLeft\">\n              <span class=\"autoW__navMark\" aria-hidden=\"true\"></span>\n              <div class=\"autoW__navText\">\n                <p class=\"autoW__itemTitle\">Business Process &amp; Operational Excellence</p>\n                <p class=\"autoW__itemHint\">Lean &amp; robust systems</p>\n              </div>\n            </div>\n            <span class=\"autoW__navArrow\" aria-hidden=\"true\">›</span>\n          </button>\n        </div>\n\n        <!-- MOBILE ACCORDION -->\n        <div class=\"autoW__mWrap\" id=\"autoW-mobile\"></div>\n      </aside>\n\n      <!-- DESKTOP RIGHT -->\n      <div class=\"autoW__right\">\n        <button class=\"autoW__ctrl autoW__ctrl--prev\" type=\"button\" aria-label=\"Previous\">‹</button>\n        <button class=\"autoW__ctrl autoW__ctrl--next\" type=\"button\" aria-label=\"Next\">›</button>\n\n        <div class=\"autoW__stage\" aria-live=\"polite\">\n          <article class=\"autoW__card is-prev\" id=\"autoW-prev\"></article>\n          <article class=\"autoW__card is-active\" id=\"autoW-active\"></article>\n          <article class=\"autoW__card is-next\" id=\"autoW-next\"></article>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<script>\n(function(){\n  const section = document.getElementById('auto-how-we-help');\n  if(!section) return;\n\n  const isElementor =\n    document.body.classList.contains('elementor-editor-active') ||\n    document.body.classList.contains('elementor-editor-preview') ||\n    !!document.querySelector('#elementor-editor-wrapper');\n\n  function enter(){ section.classList.add('is-in'); }\n\n  if(isElementor){\n    enter();\n  } else if('IntersectionObserver' in window){\n    const io = new IntersectionObserver((entries)=>{\n      entries.forEach(e=>{\n        if(e.isIntersecting){\n          enter();\n          io.unobserve(section);\n        }\n      });\n    }, { threshold: 0.25 });\n    io.observe(section);\n    setTimeout(()=>{ if(!section.classList.contains('is-in')) enter(); }, 1200);\n  } else {\n    enter();\n  }\n\n  const data = [\n    {\n      navTitle:\"Growth & Strategy\",\n      navHint:\"Future-fit choices\",\n      kicker:\"01 · Growth & Strategy\",\n      title:\"Building Future-Fit Automotive Businesses\",\n      lead:\"We help automotive organisations refine strategic direction and competitive choices in a fast-changing industry landscape.\",\n      label1:\"How we support:\",\n      bullets:[\n        \"Strategic roadmaps for EV, hybrid, and connected vehicle portfolios\",\n        \"Market entry, product strategy, and pricing models\",\n        \"Commercial excellence and customer value optimisation\",\n        \"Strategic partnerships (tech, EV infra, software vendors)\",\n        \"M&A support and synergies assessment\"\n      ],\n      impact:\"Clear growth priorities, improved portfolio execution, and strengthened market positioning.\"\n    },\n    {\n      navTitle:\"Shared Services & GCC Excellence\",\n      navHint:\"Scalable operations\",\n      kicker:\"02 · Shared Services & GCC Excellence\",\n      title:\"Scalable Operations Across Functions\",\n      lead:\"Automotive firms are increasingly centralising non-core functions to drive consistency and efficiency.\",\n      label1:\"We help with:\",\n      bullets:[\n        \"GCC and shared services set-up (engineering, analytics, finance)\",\n        \"Operating model design for global units\",\n        \"Governance, KPI frameworks, and performance standards\",\n        \"Capability and leadership development programs\"\n      ],\n      impact:\"Standardised, cost-efficient processes with alignment across geographies.\"\n    },\n    {\n      navTitle:\"Tech-Enabled Transformation\",\n      navHint:\"Digitalise value chain\",\n      kicker:\"03 · Tech-Enabled Transformation\",\n      title:\"Digitalising the Automotive Value Chain\",\n      lead:\"We enable practical digital transformation aligned with performance, compliance, and speed.\",\n      label1:\"Where we support:\",\n      bullets:[\n        \"IT/OT integration across plants\",\n        \"Smart manufacturing and connected shopfloor practices\",\n        \"Digital twin, advanced analytics, and quality prediction\",\n        \"Cloud migration and modern data platforms\",\n        \"Workflow digitisation and automation (RPA / low-code)\"\n      ],\n      impact:\"Improved real-time visibility, faster decision-making, and enhanced operational agility.\"\n    },\n    {\n      navTitle:\"ESG & Sustainable Value Creation\",\n      navHint:\"Responsible growth\",\n      kicker:\"04 · ESG & Sustainable Value Creation\",\n      title:\"ESG & Sustainable Value Creation\",\n      lead:\"Sustainability is now central to brand reputation, regulatory compliance, and investor expectations in Automotive.\",\n      label1:\"Our support includes:\",\n      bullets:[\n        \"ESG strategy & measurement aligned to global norms\",\n        \"Emissions reduction and energy optimisation programs\",\n        \"Sustainable supply chain frameworks\",\n        \"ESG reporting and assurance readiness\",\n        \"Stakeholder engagement and value communication\"\n      ],\n      impact:\"Stronger environmental stewardship, stakeholder confidence, and long-term viability.\"\n    },\n    {\n      navTitle:\"Business Process & Operational Excellence\",\n      navHint:\"Lean & robust systems\",\n      kicker:\"05 · Business Process & Operational Excellence\",\n      title:\"Creating Lean & Robust Automotive Systems\",\n      lead:\"Automotive operations demand precision, flexibility, and customer responsiveness.\",\n      label1:\"Our services include:\",\n      bullets:[\n        \"Lean transformation across production and supply chain\",\n        \"Value stream design for assembly, powertrain, and components\",\n        \"Cost optimisation and productivity improvement\",\n        \"Target operating model (TOM) design\",\n        \"Standardisation of global and regional processes\"\n      ],\n      impact:\"Lower defect rates, higher throughput, reduced cycle time, and improved customer satisfaction.\"\n    }\n  ];\n\n  /* ---------------- DESKTOP SLIDER ---------------- */\n  const navButtons = Array.from(section.querySelectorAll('.autoW__navBtn'));\n  const prevEl = section.querySelector('#autoW-prev');\n  const activeEl = section.querySelector('#autoW-active');\n  const nextEl = section.querySelector('#autoW-next');\n  const btnPrev = section.querySelector('.autoW__ctrl--prev');\n  const btnNext = section.querySelector('.autoW__ctrl--next');\n\n  let idx = 0;\n\n  function cardHTML(d){\n    return `\n      <div class=\"autoW__top\">\n        <p class=\"autoW__kicker\">${d.kicker}</p>\n        <h3 class=\"autoW__cardTitle\">${d.title}</h3>\n      </div>\n      <div class=\"autoW__body\">\n        <p class=\"autoW__lead\">${d.lead}</p>\n        <div class=\"autoW__label\">${d.label1}</div>\n        <ul class=\"autoW__list\">\n          ${d.bullets.map(x=>`<li>${x}</li>`).join('')}\n        </ul>\n        <div class=\"autoW__impact\"><b>Impact:</b> ${d.impact}</div>\n      </div>\n    `;\n  }\n\n  function setActiveNav(i){\n    navButtons.forEach((b,bi)=> b.setAttribute('aria-selected', bi===i ? 'true':'false'));\n  }\n\n  function renderDesktop(){\n    const prevI = (idx - 1 + data.length) % data.length;\n    const nextI = (idx + 1) % data.length;\n\n    if(prevEl) prevEl.innerHTML = cardHTML(data[prevI]);\n    if(activeEl) activeEl.innerHTML = cardHTML(data[idx]);\n    if(nextEl) nextEl.innerHTML = cardHTML(data[nextI]);\n    setActiveNav(idx);\n  }\n\n  function goTo(i){\n    idx = (i + data.length) % data.length;\n    renderDesktop();\n  }\n\n  navButtons.forEach(btn=>{\n    btn.addEventListener('click', ()=>{\n      const i = parseInt(btn.getAttribute('data-i'),10);\n      goTo(i);\n    });\n  });\n\n  btnPrev && btnPrev.addEventListener('click', ()=> goTo(idx-1));\n  btnNext && btnNext.addEventListener('click', ()=> goTo(idx+1));\n\n  section.addEventListener('keydown', (e)=>{\n    if(e.key === 'ArrowLeft') goTo(idx-1);\n    if(e.key === 'ArrowRight') goTo(idx+1);\n  });\n\n  renderDesktop();\n\n  /* ---------------- MOBILE ACCORDION ---------------- */\n  const mobileMount = section.querySelector('#autoW-mobile');\n\n  function mobileCard(d, i){\n    return `\n      <div class=\"autoW__mCard\" aria-expanded=\"${i===0 ? 'true':'false'}\" data-i=\"${i}\">\n        <button class=\"autoW__mBtn\" type=\"button\" aria-label=\"${d.navTitle}\">\n          <div class=\"autoW__mLeft\">\n            <span class=\"autoW__navMark\" aria-hidden=\"true\"></span>\n            <div style=\"min-width:0\">\n              <p class=\"autoW__mTitle\">${d.navTitle}</p>\n              <p class=\"autoW__mHint\">${d.navHint}</p>\n            </div>\n          </div>\n          <span class=\"autoW__mChevron\" aria-hidden=\"true\">⌄</span>\n        </button>\n\n        <div class=\"autoW__mAcc\">\n          <div class=\"autoW__mContent\">\n            <div class=\"autoW__mTop\">\n              <p class=\"autoW__mKicker\">${d.kicker}</p>\n              <h3 class=\"autoW__mCardTitle\">${d.title}</h3>\n            </div>\n            <div class=\"autoW__mBody\">\n              <p class=\"autoW__mLead\">${d.lead}</p>\n              <div class=\"autoW__mLabel\">${d.label1}</div>\n              <ul class=\"autoW__mList\">\n                ${d.bullets.map(x=>`<li>${x}</li>`).join('')}\n              </ul>\n              <div class=\"autoW__mImpact\"><b>Impact:</b> ${d.impact}</div>\n            </div>\n          </div>\n        </div>\n      </div>\n    `;\n  }\n\n  function renderMobile(){\n    if(!mobileMount) return;\n    mobileMount.innerHTML = data.map((d,i)=>mobileCard(d,i)).join('');\n\n    const cards = Array.from(mobileMount.querySelectorAll('.autoW__mCard'));\n    cards.forEach(card=>{\n      const btn = card.querySelector('.autoW__mBtn');\n      btn.addEventListener('click', ()=>{\n        const isOpen = card.getAttribute('aria-expanded') === 'true';\n        cards.forEach(c=>c.setAttribute('aria-expanded','false'));\n        card.setAttribute('aria-expanded', isOpen ? 'false' : 'true');\n      });\n    });\n  }\n\n  renderMobile();\n})();\n</script>\n\n<!-- ===================== AUTOMOTIVE — WHY WORK WITH US (IMAGE LEFT) ===================== -->\n<link href=\"https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700;800&display=swap\" rel=\"stylesheet\"/>\n\n<style>\n:root{\n  --navy:#020C4F;\n  --indigo:#313B86;\n  --violet:#625AD8;\n  --accent:#1F9CE4;\n\n  --ink:#0B0F1A;\n  --muted:#3C4160;\n}\n\n/* SECTION */\n.autoWhy, .autoWhy *{box-sizing:border-box;}\n.autoWhy{\n  padding:96px 20px;\n  font-family:'Poppins',system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;\n  background:\n    radial-gradient(circle at 18% 0%, rgba(98,90,216,.08), transparent 55%),\n    radial-gradient(circle at 95% 30%, rgba(49,59,134,.08), transparent 55%),\n    radial-gradient(circle at 70% 110%, rgba(2,12,79,.06), transparent 60%),\n    rgba(49,59,134,.03);\n}\n\n.autoWhy__inner{\n  max-width:1200px;\n  margin:0 auto;\n  display:grid;\n  grid-template-columns:1.05fr 0.95fr;\n  gap:44px;\n  align-items:stretch;\n}\n\n/* IMAGE COLUMN */\n.autoWhy__imageWrap{\n  position:relative;\n  border-radius:26px;\n  overflow:hidden;\n  min-height:460px;\n  box-shadow:0 22px 54px rgba(0,0,0,.10);\n}\n\n.autoWhy__imageWrap img{\n  position:absolute;\n  inset:0;\n  width:100%;\n  height:100%;\n  object-fit:cover;\n  display:block;\n}\n\n/* brand overlay */\n.autoWhy__imageWrap::after{\n  content:\"\";\n  position:absolute;\n  inset:0;\n  background:\n    linear-gradient(180deg, rgba(2,12,79,.18), rgba(2,12,79,.08) 55%, rgba(255,255,255,0) 100%),\n    radial-gradient(circle at 20% 20%, rgba(98,90,216,.20), transparent 60%),\n    radial-gradient(circle at 80% 35%, rgba(31,156,228,.16), transparent 60%);\n  pointer-events:none;\n}\n\n/* CONTENT COLUMN */\n.autoWhy__content{\n  display:flex;\n  flex-direction:column;\n  justify-content:center;\n}\n\n.autoWhy__eyebrow{\n  font-size:12px;\n  letter-spacing:.18em;\n  text-transform:uppercase;\n  color:var(--indigo);\n  font-weight:800;\n  margin:0 0 10px;\n}\n\n.autoWhy__title{\n  font-size:clamp(32px,3.6vw,46px);\n  line-height:1.1;\n  font-weight:900;\n  color:var(--navy);\n  margin:0 0 18px;\n}\n\n/* MANIFESTO LIST */\n.autoWhy__list{\n  list-style:none;\n  margin:0;\n  padding:0;\n  display:grid;\n  gap:18px;\n  position:relative;\n}\n\n.autoWhy__list::before{\n  content:\"\";\n  position:absolute;\n  left:14px;\n  top:6px;\n  bottom:6px;\n  width:2px;\n  background:linear-gradient(180deg, rgba(98,90,216,.45), rgba(31,156,228,.35));\n  opacity:.6;\n}\n\n.autoWhy__item{\n  position:relative;\n  padding-left:46px;\n}\n\n.autoWhy__dot{\n  position:absolute;\n  left:6px;\n  top:4px;\n  width:18px;\n  height:18px;\n  border-radius:50%;\n  background:#fff;\n  border:1px solid rgba(49,59,134,.25);\n}\n\n.autoWhy__dot::after{\n  content:\"\";\n  position:absolute;\n  inset:4px;\n  border-radius:50%;\n  background:linear-gradient(135deg,var(--violet),var(--accent));\n  box-shadow:0 0 0 6px rgba(31,156,228,.12);\n}\n\n.autoWhy__h{\n  margin:0 0 4px;\n  font-size:16px;\n  font-weight:800;\n  color:var(--navy);\n}\n\n.autoWhy__p{\n  margin:0;\n  font-size:14.8px;\n  line-height:1.75;\n  color:#3C4160;\n}\n\n/* MOBILE */\n@media(max-width:980px){\n  .autoWhy{padding:78px 18px;}\n  .autoWhy__inner{grid-template-columns:1fr; gap:26px;}\n  .autoWhy__imageWrap{min-height:260px;}\n  .autoWhy__list::before{left:12px;}\n}\n</style>\n\n<section class=\"autoWhy\" id=\"auto-why-us\">\n  <div class=\"autoWhy__inner\">\n\n    <!-- IMAGE LEFT -->\n    <div class=\"autoWhy__imageWrap\">\n      <img\n        src=\"https://mediumpurple-ant-531485.hostingersite.com/wp-content/uploads/2025/12/marc-olivier-jodoin-K9GMQEETUAw-unsplash-scaled.jpg\"\n        alt=\"Automotive transformation and mobility innovation\"\n      />\n    </div>\n\n    <!-- CONTENT RIGHT -->\n    <div class=\"autoWhy__content\">\n      <p class=\"autoWhy__eyebrow\">Automotive Sector</p>\n      <h2 class=\"autoWhy__title\">Why Automotive Organisations Work With Us</h2>\n\n      <ul class=\"autoWhy__list\">\n        <li class=\"autoWhy__item\">\n          <span class=\"autoWhy__dot\"></span>\n          <p class=\"autoWhy__h\">Strategy + Execution as One System</p>\n          <p class=\"autoWhy__p\">\n            We turn strategic intent into measurable operational performance across the automotive value chain.\n          </p>\n        </li>\n\n        <li class=\"autoWhy__item\">\n          <span class=\"autoWhy__dot\"></span>\n          <p class=\"autoWhy__h\">Deep Understanding of Complex, Regulated Environments</p>\n          <p class=\"autoWhy__p\">\n            Solutions are designed for safety, quality, compliance, and audit readiness by default.\n          </p>\n        </li>\n\n        <li class=\"autoWhy__item\">\n          <span class=\"autoWhy__dot\"></span>\n          <p class=\"autoWhy__h\">Tech-First, Human-Centric Approach</p>\n          <p class=\"autoWhy__p\">\n            Digital initiatives enhance human judgment and execution discipline — not replace them.\n          </p>\n        </li>\n\n        <li class=\"autoWhy__item\">\n          <span class=\"autoWhy__dot\"></span>\n          <p class=\"autoWhy__h\">Proven, Integrated Methodologies</p>\n          <p class=\"autoWhy__p\">\n            Lean, Industry 4.0, Agile, ESG, TOM, and transformation frameworks — woven into one system.\n          </p>\n        </li>\n\n        <li class=\"autoWhy__item\">\n          <span class=\"autoWhy__dot\"></span>\n          <p class=\"autoWhy__h\">Measurable Outcomes</p>\n          <p class=\"autoWhy__p\">\n            Every engagement is tied to growth, cost, quality, or customer experience metrics.\n          </p>\n        </li>\n      </ul>\n    </div>\n\n  </div>\n</section>\n\n<!-- ===================== AUTOMOTIVE — FINAL CTA (WHITE BACKGROUND STRIP) ===================== -->\n<link href=\"https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700;800&display=swap\" rel=\"stylesheet\"/>\n\n<style>\n:root{\n  --navy:#020C4F;\n  --indigo:#313B86;\n  --violet:#625AD8;\n  --accent:#1F9CE4;\n\n  --ink:#0B0F1A;\n  --muted:#3C4160;\n  --line:rgba(49,59,134,.16);\n}\n\n.auto-cta, .auto-cta *{box-sizing:border-box;}\n.auto-cta{\n  padding:84px 20px;\n  font-family:'Poppins',system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;\n  background:#ffffff; /* white strip */\n}\n\n.auto-cta__inner{\n  max-width:1200px;\n  margin:0 auto;\n}\n\n.auto-cta__bar{\n  border:1px solid rgba(49,59,134,.16);\n  border-radius:26px;\n  background:rgba(255,255,255,.98);\n  box-shadow:0 22px 54px rgba(0,0,0,.08);\n  padding:28px 28px;\n  display:flex;\n  align-items:center;\n  justify-content:space-between;\n  gap:22px;\n}\n\n.auto-cta__left{\n  min-width:0;\n  max-width:820px;\n}\n\n.auto-cta__kicker{\n  margin:0 0 10px;\n  font-size:12px;\n  letter-spacing:.18em;\n  text-transform:uppercase;\n  color:var(--indigo);\n  font-weight:800;\n}\n\n.auto-cta__title{\n  margin:0 0 10px;\n  font-size:clamp(26px,3.2vw,38px);\n  line-height:1.15;\n  font-weight:900;\n  color:var(--navy);\n}\n\n.auto-cta__text{\n  margin:0;\n  font-size:15.5px;\n  line-height:1.75;\n  color:var(--muted);\n}\n\n/* signal pill */\n.auto-cta__pill{\n  display:inline-flex;\n  align-items:center;\n  gap:10px;\n  padding:9px 12px;\n  border-radius:999px;\n  border:1px solid rgba(49,59,134,.18);\n  background:rgba(49,59,134,.04);\n  color:var(--indigo);\n  font-weight:800;\n  font-size:12px;\n  margin-top:14px;\n  flex-wrap:wrap;\n}\n\n.auto-cta__dot{\n  width:9px;height:9px;border-radius:999px;\n  background:linear-gradient(135deg,var(--violet),var(--accent));\n  box-shadow:0 0 0 6px rgba(31,156,228,.10);\n}\n\n.auto-cta__right{\n  flex:0 0 auto;\n  display:flex;\n  gap:12px;\n  flex-wrap:wrap;\n  justify-content:flex-end;\n}\n\n.auto-cta__btn{\n  height:46px;\n  padding:0 18px;\n  border-radius:999px;\n  display:inline-flex;\n  align-items:center;\n  justify-content:center;\n  gap:10px;\n  font-size:14px;\n  font-weight:800;\n  text-decoration:none;\n  transition:.2s ease;\n  white-space:nowrap;\n}\n\n.auto-cta__btn--primary{\n  background:var(--violet);\n  color:#fff;\n  border:1px solid var(--violet);\n  box-shadow:0 12px 26px rgba(98,90,216,.22);\n}\n.auto-cta__btn--primary:hover{\n  background:var(--accent);\n  border-color:var(--accent);\n  transform:translateY(-1px);\n}\n\n.auto-cta__btn--ghost{\n  background:#fff;\n  color:var(--navy);\n  border:1px solid rgba(49,59,134,.22);\n}\n.auto-cta__btn--ghost:hover{\n  background:rgba(49,59,134,.04);\n  transform:translateY(-1px);\n}\n\n@media (max-width:980px){\n  .auto-cta{padding:70px 18px;}\n  .auto-cta__bar{\n    padding:22px;\n    flex-direction:column;\n    align-items:flex-start;\n  }\n  .auto-cta__right{justify-content:flex-start;}\n}\n</style>\n\n<section class=\"auto-cta\" id=\"auto-cta\">\n  <div class=\"auto-cta__inner\">\n\n    <div class=\"auto-cta__bar\">\n      <div class=\"auto-cta__left\">\n        <p class=\"auto-cta__kicker\">Next steps</p>\n        <h2 class=\"auto-cta__title\">Let’s Build the Next-Gen Automotive Enterprise</h2>\n        <p class=\"auto-cta__text\">\n          From strategy and shared services to digital transformation, ESG, and operational excellence, we help\n          Automotive organisations accelerate performance, strengthen resilience, and compete at global scale.\n        </p>\n\n        <div class=\"auto-cta__pill\">\n          <span class=\"auto-cta__dot\" aria-hidden=\"true\"></span>\n          Strategy • Shared Services • Digital • ESG • Operational Excellence\n        </div>\n      </div>\n\n      <div class=\"auto-cta__right\">\n        <a class=\"auto-cta__btn auto-cta__btn--ghost\" href=\"/contact-us\">Talk to us</a>\n        <a class=\"auto-cta__btn auto-cta__btn--primary\" href=\"/contact-us\">Request a consultation →</a>\n      </div>\n    </div>\n\n  </div>\n</section>";
